use std::fmt::Write;

use crate::graph::Graph;

/// Export model coordinates, independent of the editor's viewport and theme.
pub fn to_cetz(graph: &Graph) -> String {
    let mut output = String::from(
        "// Generated by Conway Topograph. 100 editor units = 1 cm.\n\
         #import \"@preview/cetz:0.5.2\"\n\n\
         #let topograph(unit: 1cm) = cetz.canvas(length: unit, {\n\
         \x20 import cetz.draw: *\n",
    );
    let left = graph
        .nodes
        .iter()
        .map(|p| p[0] as f64)
        .reduce(f64::min)
        .unwrap_or(0.0);
    let bottom = graph
        .nodes
        .iter()
        .map(|p| p[1] as f64)
        .reduce(f64::max)
        .unwrap_or(0.0);
    let points: Vec<[f64; 2]> = graph
        .nodes
        .iter()
        .map(|&[x, y]| [(x as f64 - left) / 100.0, (bottom - y as f64) / 100.0])
        .collect();
    for (index, &[a, b]) in graph.edges.iter().enumerate() {
        let a = points[a];
        let b = points[b];
        writeln!(output, "  // Edge {}", index + 1).unwrap();
        if graph.double_edges.contains(&index) {
            let dx = b[0] - a[0];
            let dy = b[1] - a[1];
            let length = dx.hypot(dy);
            let offset = if length > 0.0 {
                [-dy / length * 0.03, dx / length * 0.03]
            } else {
                [0.0, 0.0]
            };
            for sign in [-1.0, 1.0] {
                write_line(
                    &mut output,
                    [a[0] + sign * offset[0], a[1] + sign * offset[1]],
                    [b[0] + sign * offset[0], b[1] + sign * offset[1]],
                );
            }
        } else {
            write_line(&mut output, a, b);
        }
    }
    output.push_str("  // Nodes (drawn over edges)\n");
    for (index, [x, y]) in points.iter().enumerate() {
        writeln!(
            output,
            "  circle(({x:.6}, {y:.6}), radius: 0.04, fill: black, stroke: none) // Node {}",
            index + 1
        )
        .unwrap();
    }
    output.push_str("})\n\n#topograph()\n");
    output
}

fn write_line(output: &mut String, a: [f64; 2], b: [f64; 2]) {
    writeln!(
        output,
        "  line(({:.6}, {:.6}), ({:.6}, {:.6}), stroke: 0.7pt + black)",
        a[0], a[1], b[0], b[1]
    )
    .unwrap();
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample() -> Graph {
        let mut graph = Graph::default();
        for p in [[-100.0, 20.0], [100.0, 20.0], [0.0, 120.0], [0.0, -80.0]] {
            graph.add_node(p);
        }
        for end in 1..=3 {
            graph.connect(0, end).unwrap();
        }
        graph.double_edges.insert(1);
        graph
    }

    #[test]
    fn export_preserves_geometry_and_double_edges() {
        let graph = sample();
        let source = to_cetz(&graph);
        assert_eq!(source.matches("  line(").count(), 4);
        assert_eq!(source.matches("  circle(").count(), 4);
        assert!(source.contains("circle((0.000000, 1.000000)"));
        assert!(source.contains("circle((1.000000, 0.000000)"));
        let mut translated = graph.clone();
        for p in &mut translated.nodes {
            p[0] += 1000.0;
            p[1] -= 500.0;
        }
        assert_eq!(source, to_cetz(&translated));
    }

    #[test]
    fn empty_and_coincident_nodes_export_finite_coordinates() {
        assert!(!to_cetz(&Graph::default()).contains("circle("));
        let mut graph = Graph::default();
        graph.add_node([0.0, 0.0]);
        graph.add_node([0.0, 0.0]);
        graph.connect(0, 1).unwrap();
        graph.double_edges.insert(0);
        let source = to_cetz(&graph);
        assert!(!source.contains("NaN"));
        assert!(!source.contains("inf"));
    }

    #[test]
    #[ignore = "requires Typst CLI and CeTZ 0.5.2"]
    fn typst_compiles_export_and_include() {
        let dir = std::env::temp_dir().join(format!("conway-cetz-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        for (name, graph) in [("sample", sample()), ("empty", Graph::default())] {
            std::fs::write(dir.join(format!("{name}.typ")), to_cetz(&graph)).unwrap();
            let wrapper = dir.join("main.typ");
            std::fs::write(&wrapper, format!("#set page(width: auto, height: auto, margin: 10pt)\n#include \"{name}.typ\"\n#import \"{name}.typ\": topograph\n#topograph(unit: 2cm)\n")).unwrap();
            let result = std::process::Command::new("typst")
                .arg("compile")
                .arg(&wrapper)
                .arg(dir.join(format!("{name}.svg")))
                .output()
                .unwrap();
            assert!(
                result.status.success(),
                "{}",
                String::from_utf8_lossy(&result.stderr)
            );
        }
        eprintln!("Compiled exports: {}", dir.display());
    }
}
